const ChaoticIcons: React.FC<ChaoticIconsProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 10,
  iconColor = "#ffffff",
  lineColor = "#444444",
  chaosAmplitude = 300,
  chaosSpeed = 0.5,
  iconSize = 64,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Calculate positions for all icons based on noise
  const positions = React.useMemo(() => {
    return ICONS.map((icon, index) => {
      // Create stable but random seeds for each icon
      const seedX = `x-${icon.id}-${index}`;
      const seedY = `y-${icon.id}-${index}`;
      
      // Base position (distributed somewhat evenly initially to avoid clumping, but then chaotic)
      // We map the noise (-1 to 1) to the canvas size + amplitude
      // Center + Noise * Amplitude
      const baseX = width / 2;
      const baseY = height / 2;

      // We add a large offset to the noise input to desynchronize them
      const timeOffset = index * 1000; 
      
      const nX = noise2D(seedX, (frame * chaosSpeed + timeOffset) * 0.01, 0);
      const nY = noise2D(seedY, (frame * chaosSpeed + timeOffset) * 0.01, 0);

      const x = baseX + nX * chaosAmplitude;
      const y = baseY + nY * chaosAmplitude;

      return { ...icon, x, y };
    });
  }, [frame, chaosSpeed, chaosAmplitude, width, height]);

  // Generate lines connecting icons
  // To make it look "tangled" but not a complete mess, we can connect each icon to 2-3 others nearby or randomly
  // For true chaos, let's just connect random pairs determined by a seed
  const lines = React.useMemo(() => {
    const connections: {x1: number, y1: number, x2: number, y2: number, key: string}[] = [];
    
    // Connect each icon to the next 2 icons in the list (wrapping around)
    // This creates a continuous tangled loop/web
    for (let i = 0; i < positions.length; i++) {
        const p1 = positions[i];
        
        // Connect to next
        const p2 = positions[(i + 1) % positions.length];
        connections.push({
            x1: p1.x, y1: p1.y, x2: p2.x, y2: p2.y, key: `link-${i}-${(i+1)%positions.length}`
        });

        // Connect to the one after next (skip one) for more tangles
        const p3 = positions[(i + 2) % positions.length];
        connections.push({
            x1: p1.x, y1: p1.y, x2: p3.x, y2: p3.y, key: `link-${i}-${(i+2)%positions.length}`
        });
    }
    return connections;
  }, [positions]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", overflow: "hidden" }}>
      
      {/* Tangled Lines Layer */}
      <svg
        width={width}
        height={height}
        style={{ position: "absolute", top: 0, left: 0 }}
      >
        {lines.map((line) => (
          <line
            key={line.key}
            x1={line.x1}
            y1={line.y1}
            x2={line.x2}
            y2={line.y2}
            stroke={lineColor}
            strokeWidth={2}
            strokeOpacity={0.4}
            strokeLinecap="round"
          />
        ))}
      </svg>

      {/* Icons Layer */}
      {positions.map((icon) => (
        <div
            key={icon.id}
            style={{
                position: "absolute",
                left: icon.x - iconSize / 2,
                top: icon.y - iconSize / 2,
                width: iconSize,
                height: iconSize,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                opacity: icon.isMissing ? 0.4 : 1,
            }}
        >
            <svg
                width="100%"
                height="100%"
                viewBox="0 0 24 24"
                fill="none"
                stroke={iconColor}
                strokeWidth={icon.isMissing ? 1.5 : 2}
                strokeLinecap="round"
                strokeLinejoin="round"
                style={{
                    overflow: "visible",
                    strokeDasharray: icon.isMissing ? "4,4" : "none",
                }}
            >
                {icon.type === "path" ? (
                    <path d={icon.data} />
                ) : (
                    <text 
                        x="12" 
                        y="16" 
                        textAnchor="middle" 
                        fontSize="10" 
                        fontWeight="bold" 
                        fill={iconColor} 
                        stroke="none"
                        style={{ opacity: icon.isMissing ? 0.5 : 1 }}
                    >
                        {icon.data}
                    </text>
                )}
            </svg>
            
            {/* Optional Label for clarity if needed, but request didn't strictly ask for text labels, just icons. 
                Keeping it icon-focused for cleaner look. */}
        </div>
      ))}

    </AbsoluteFill>
  );
};

export default ChaoticIcons;